import pandas as pd, numpy as np, re
from statsmodels.tsa.filters.hp_filter import hpfilter

def parse(file):
    df=pd.read_excel(file, header=None)
    annual={}
    q=[]
    in2024=False
    for _,row in df.iterrows():
        s=row[0]
        if not isinstance(s,str):
            continue
        t=s.strip()
        m=re.fullmatch(r'(\d{4})\.', t)
        if m:
            annual[int(m.group(1))]=float(row[1])
            in2024=False
            continue
        if t.startswith('2024: I.'):
            q=[float(row[1])]
            in2024=True
            continue
        if in2024 and re.fullmatch(r'(II|III|IV)(?: p\.)?\.', t):
            q.append(float(row[1]))
            continue
        if in2024 and t.startswith('Source:'):
            in2024=False
    return annual, q

for f in ['/root/ERP-2025-table10.xls','/root/ERP-2025-table12.xls']:
    annual,q=parse(f)
    print(f, q, sum(q)/len(q))
